           rules: {
             filters: tempFilters ?? [],
           },
-      });
-      setTempFilters(null);
+        });
+        setTempFilters(null);
+      } catch (e) {
+        console.error('Failed to update collection', e);
+        // optional: surface toast / notification here
+      }
```

Same applies in the “create-and-pin” branch inside `openPromptModal`.  



