@@ -0,0 +1,96 @@
+---
+layout: default
+title: Index phrases
+parent: Mapping parameters
+grand_parent: Mapping and field types
+nav_order: 80
+has_children: false
+has_toc: false
+---
+
+# Index phrases
+
+The `index_phrases` mapping parameter determines whether a field's text is additionally processed to generate phrase tokens. When enabled, the system creates extra tokens representing sequences of exactly two consecutive words (_bigrams_). This can significantly improve the performance and accuracy of phrase queries. However, it also increases the index size and the time needed to index documents.
+
+By default, `index_phrases` is set to `false`, to maintain a leaner index and faster document ingestion.
+
+## Enabling index phrases on a field
+
+The following example creates an index named `blog` in which the `content` field is configured with `index_phrases`:
+
+```json
+PUT /blog
+{
+  "mappings": {
+    "properties": {
+      "content": {
+        "type": "text",
+        "index_phrases": true
+      }
+    }
+  }
+}
+```
+{% include copy-curl.html %}
+
+Index a document using the following request:
+
+```json
+PUT /blog/_doc/1
+{
+  "content": "The slow green turtle swims past the whale"
+}
+```
+{% include copy-curl.html %}
+
+Perform a `match_phrase` query using the following search request:
+
+```json
+POST /blog/_search
+{
+  "query": {
+    "match_phrase": {
+      "content": "slow green"
+    }
+  }
+}
+```
+{% include copy-curl.html %}
+
+The query returns the stored document:
+
+```json
+{
+  "took": 25,
+  "timed_out": false,
+  "_shards": {
+    "total": 1,
+    "successful": 1,
+    "skipped": 0,
+    "failed": 0
+  },
+  "hits": {
+    "total": {
+      "value": 1,
+      "relation": "eq"
+    },
+    "max_score": 0.5753642,
+    "hits": [
+      {
+        "_index": "blog",
+        "_id": "1",
+        "_score": 0.5753642,
+        "_source": {
+          "content": "The slow green turtle swims past the whale"
+        }
+      }
+    ]
+  }
+}
+```
+
+Although the same hit is returned when you don't provide the `index_phrases` mapping parameter, using this parameter ensures that the query performs as follows:
+
+- Uses the `.index_phrases` field internally.
+- Matches pre-tokenized bigrams such as "slow green", "green turtle", "turtle swims".

@@ -0,0 +1,361 @@
+use {
+    super::{list_view::ListView, Result, VoteStateViewError},
+    solana_clock::{Epoch, Slot},
+    solana_pubkey::Pubkey,
+    std::io::BufRead,
+};
+
+pub(super) trait ListFrame {
+    type Item;
+
+    // SAFETY: Each implementor MUST enforce that `Self::Item` is alignment 1 to
+    // ensure that after casting it won't have alignment issues, any heap
+    // allocated fields, or any assumptions about endianness.
+    #[cfg(test)]
+    const ASSERT_ITEM_ALIGNMENT: ();
+
+    fn len(&self) -> usize;
+    fn item_size(&self) -> usize {
+        core::mem::size_of::<Self::Item>()
+    }
+
+    /// This function is safe under the following conditions:
+    /// SAFETY:
+    /// - `Self::Item` is alignment 1
+    /// - The passed `item_data` slice is large enough for the type `Self::Item`
+    /// - `Self::Item` is valid for any sequence of bytes
+    unsafe fn read_item<'a>(&self, item_data: &'a [u8]) -> &'a Self::Item {
+        &*(item_data.as_ptr() as *const Self::Item)
+    }
+
+    fn total_size(&self) -> usize {
+        core::mem::size_of::<u64>() /* len */ + self.total_item_size()
+    }
+
+    fn total_item_size(&self) -> usize {
+        self.len() * self.item_size()
+    }
+}
+
+pub(super) enum VotesFrame {
+    Lockout(LockoutListFrame),
+    Landed(LandedVotesListFrame),
+}
+
+impl ListFrame for VotesFrame {
+    type Item = LockoutItem;
+
+    #[cfg(test)]
+    const ASSERT_ITEM_ALIGNMENT: () = {
+        static_assertions::const_assert!(core::mem::align_of::<LockoutItem>() == 1);
+    };
+
+    fn len(&self) -> usize {
+        match self {
+            Self::Lockout(frame) => frame.len(),
+            Self::Landed(frame) => frame.len(),
+        }
+    }
+
+    fn item_size(&self) -> usize {
+        match self {
+            Self::Lockout(frame) => frame.item_size(),
+            Self::Landed(frame) => frame.item_size(),
+        }
+    }
+
+    unsafe fn read_item<'a>(&self, item_data: &'a [u8]) -> &'a Self::Item {
+        match self {
+            Self::Lockout(frame) => frame.read_item(item_data),
+            Self::Landed(frame) => frame.read_item(item_data),
+        }
+    }
+}
+
+#[repr(C)]
+pub(super) struct LockoutItem {
+    slot: [u8; 8],
+    confirmation_count: [u8; 4],
+}
+
+impl LockoutItem {
+    #[inline]
+    pub(super) fn slot(&self) -> Slot {
+        u64::from_le_bytes(self.slot)
+    }
+    #[inline]
+    pub(super) fn confirmation_count(&self) -> u32 {
+        u32::from_le_bytes(self.confirmation_count)
+    }
+}
+
+#[derive(Debug, Clone, Copy)]
+#[cfg_attr(feature = "frozen-abi", derive(AbiExample))]
+pub(super) struct LockoutListFrame {
+    len: u8,
+}
+
+impl LockoutListFrame {
+    pub(super) fn read(cursor: &mut std::io::Cursor<&[u8]>) -> Result<Self> {
+        let len = solana_serialize_utils::cursor::read_u64(cursor)
+            .map_err(|_err| VoteStateViewError::ParseError)? as usize;
+        let len = u8::try_from(len).map_err(|_| VoteStateViewError::ParseError)?;
+        let frame = Self { len };
+        cursor.consume(frame.total_item_size());
+        Ok(frame)
+    }
+}
+
+impl ListFrame for LockoutListFrame {
+    type Item = LockoutItem;
+
+    #[cfg(test)]
+    const ASSERT_ITEM_ALIGNMENT: () = {
+        static_assertions::const_assert!(core::mem::align_of::<LockoutItem>() == 1);
+    };
+
+    fn len(&self) -> usize {
+        self.len as usize
+    }
+}
+
+#[derive(Debug, Clone, Copy)]
+#[cfg_attr(feature = "frozen-abi", derive(AbiExample))]
+pub(super) struct LandedVotesListFrame {
+    len: u8,
+}
+
+impl LandedVotesListFrame {
+    pub(super) fn read(cursor: &mut std::io::Cursor<&[u8]>) -> Result<Self> {
