+	public function get_items( $request ) {
+		// We only support this endpoint for self-hosted sites.
+		if ( Utils::is_wpcom() ) {
+			return new WP_Error( 'invalid_request', 'This endpoint is not available for WordPress.com sites.', array( 'status' => 404 ) );
+		}

