+}
+
+impl Decoder for CrLfNormalizer {
+    type Item = BytesMut;
+    type Error = io::Error;
+
+    fn decode(&mut self, src: &mut BytesMut) -> Result<Option<Self::Item>, Self::Error> {
+        if src.is_empty() {
+            return if std::mem::replace(&mut self.pending_cr, false) {
+                Ok(Some(BytesMut::from(&b"\n"[..])))
+            } else {
+                Ok(None)
+            };
