+        }
+    }
+
+    pub(super) fn read(cursor: &mut std::io::Cursor<&[u8]>) -> Result<Self> {
+        let has_root_slot = solana_serialize_utils::cursor::read_bool(cursor)
+            .map_err(|_err| VoteStateViewError::ParseError)?;
